import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

const email = atom({ plugin: 'ccwhoami', key: 'email' } as const, null)

const EMAIL = /[^\s@]+@[^\s@]+\.[^\s@.]+/

// `claude auth status` prints the same account /status shows, as JSON.
async function refresh($: EngineInterface) {
  let out = ''
  let found: string | null = null
  try {
    for await (const { stream, text } of $.process.spawn({ argv: ['claude', 'auth', 'status'] })) {
      if (stream === 'stdout') out += text
    }
    const status = JSON.parse(out)
    if (status.loggedIn && typeof status.email === 'string') found = status.email
  } catch {}
  await update($, email, () => found)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    void refresh($)
    return started
  })

  // Re-read after the account changes.
  for (const command of ['login', 'logout']) {
    on('command.run', { command }, async ($, e, next) => {
      const result = await next(e)
      void refresh($)
      return result
    })
  }

  // Fallback: the userEmail context block carries the same address.
  on('prompt.context', async ($, e, next) => {
    const found = e.blocks.find(b => b.name === 'userEmail')?.text.match(EMAIL)?.[0]
    if (found && (await read($, email)) === null) await update($, email, () => found)
    return next(e)
  })

  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const current = await read($, email)
    if (!current) return next(e)
    return next({ ...e, props: { ...e.props, modes: [...e.props.modes, current] } })
  })
}

